c=json.loads((p/'research/americas-coverage.json').read_text())
c['partiallyScreened']=[x for x in c['partiallyScreened'] if (x['competition'],x['year'])!=('OBM Level 2',2022)]
c['partiallyScreened'].append(dict(competition='OBM Level 2',year=2022,ratings={'1':3.5,'2':5,'5':5.5,'6':6.5},pending=['3','4']))
c['problemAppearancesScreened']=sum(len(x['ratings']) for x in c['fullyScreened']+c['partiallyScreened'])
c['uniqueIncluded']=len(data)
(p/'research/americas-coverage.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
